def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    motorcycle_patches = image_patch.find("motorcycle")

    if not man_patches or not motorcycle_patches:
        return image_patch

    man_centers = [(p.left + p.right) / 2 for p in man_patches]
    motorcycle_centers = [(p.left + p.right) / 2 for p in motorcycle_patches]

    closest_man = min(man_centers, key=lambda x: abs(x - motorcycle_centers[0]))
    man_index = man_centers.index(closest_man)

    man_patch = man_patches[man_index]
    motorcycle_patch = motorcycle_patches[0]

    if man_patch.overlaps_with(motorcycle_patch.left, motorcycle_patch.lower, motorcycle_patch.right, motorcycle_patch.upper):
        return man_patch

    man_left = man_patch.left < motorcycle_patch.left
    man_right = man_patch.right > motorcycle_patch.right

    if man_left and man_right:
        return man_patch
    elif man_left:
        return man_patch.crop(motorcycle_patch.right, man_patch.lower, man_patch.right, man_patch.upper)
    else:
        return man_patch.crop(man_patch.left, man_patch.lower, motorcycle_patch.left, man_patch.upper)

